'use client';
import {readServiceInventory} from '@/lib/service-inventory';
import {ServiceInventoryReview} from '@/components/service-inventory-review';
import {serviceUsageLabel} from '@/lib/service-days';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc,usd,formText,cents} from '@/lib/pilot';
import {afterDays} from '@/lib/rates';
import {useClientReady} from '@/lib/client-ready';
import {Dialog,DialogContent,DialogTitle,DialogDescription} from '@/components/ui/dialog';
import {useServiceRequest,PendingServiceRequest} from '@/components/service-request';
import {ServiceForwardPanel,PendingForwardList} from '@/components/service-forward';
import {ClosedServiceReports} from '@/components/service-reports';
import {ServiceTotalsBreakdown} from '@/components/service-totals';
import {serviceComponents,blockerLabel,type ServicePreview,type ServiceCommand,type ServiceReceipt,type ServiceAllocation,type AllocationInput} from '@/lib/service-days';
type Props={actor:string;tenant:string;property:string;propertyName:string;timeZone:string;businessDate:string;role:string;onBusyChange:(busy:boolean)=>void};
export function ServiceDayPanel(props:Props){return useClientReady()?<ServiceDayForm {...props}/>:<p>Loading service-day requests…</p>}
function ServiceDayForm({actor,tenant,property,propertyName,timeZone,businessDate,role,onBusyChange}:Props){
 const [preview,setPreview]=useState<ServicePreview|null>(null),[readError,setReadError]=useState(''),[notice,setNotice]=useState(''),[allocation,setAllocation]=useState<string|null>(null),[forward,setForward]=useState<string|null>(null),[reportRevision,setReportRevision]=useState(0),[allocationBusy,setAllocationBusy]=useState(false);const alive=useRef(true),sequence=useRef(0);const manager=['owner','manager'].includes(role);
 const request=useServiceRequest('iratepilot-pms-pending-service-day:'+actor+':'+tenant+':'+property,tenant,property,onBusyChange);
 async function refresh(){const seq=++sequence.current;setPreview(null);setReadError('');try{const result=await hotelRpc<ServicePreview>('service_day_preview_v2',{p_tenant:tenant,p_property:property});if(result.inventory_snapshot!==undefined)readServiceInventory(result.inventory_snapshot,result.next_service_date!);if(alive.current&&sequence.current===seq)setPreview(result)}catch(e){if(alive.current&&sequence.current===seq)setReadError(e instanceof Error?e.message:'Unable to read service-day preview.')}}
 useEffect(()=>{alive.current=true;const seq=++sequence.current;hotelRpc<ServicePreview>('service_day_preview_v2',{p_tenant:tenant,p_property:property}).then(result=>{if(result.inventory_snapshot!==undefined)readServiceInventory(result.inventory_snapshot,result.next_service_date!);if(alive.current&&sequence.current===seq){setPreview(result);setReadError('')}}).catch(e=>{if(alive.current&&sequence.current===seq)setReadError(e instanceof Error?e.message:'Unable to read service-day preview.')});return()=>{alive.current=false}},[tenant,property]);
 async function save(command:ServiceCommand){await request.run<ServiceReceipt>(command,async result=>{setNotice((command.rpc==='close_service_day'||command.rpc==='close_service_day_v2')?'Service day '+result.service_date+' closed'+(result.replayed?' (confirmed existing close)':'')+'. Next service day: '+result.next_service_date+'.':'Service ledger started from '+result.next_service_date+'.');setReportRevision(v=>v+1);await refresh()},()=>{void refresh()})}
 return <><section className="card pilot-service-close"><div className="section-top"><div><h2>Service-day close</h2><p>Allocate charges to service nights and preserve a closed daily report.</p></div><button className="secondary" disabled={request.busy||!!request.pending} onClick={()=>void refresh()}>Refresh preview</button></div><div className="pilot-service-body"><p className="pilot-report-basis">This ledger records nightly revenue allocations. It does not collect payments, change folio balances, or replace general-ledger and settlement accounting. Front-desk dates continue to follow {timeZone}.</p>{(request.error||readError)&&<div className="pilot-error" role="alert">{request.error||readError}</div>}{notice&&<output className="pilot-notice">{notice}</output>}{request.pending?<PendingServiceRequest command={request.pending} busy={request.busy} onRetry={()=>void save(request.pending!)}/>:!preview?<p>Load the latest service-day preview to continue.</p>:!preview.initialized?<>{role==='owner'?<form className="pilot-service-start" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void save({rpc:'start_service_ledger',label:'Start the service ledger on '+formText(f,'first'),params:{p_request:crypto.randomUUID(),p_first_service_date:formText(f,'first'),p_reason:formText(f,'reason').trim()}})}}><h3>Choose the first service day</h3><p>Earlier dates will not be backfilled. Review this starting date before saving; the ledger advances one closed day at a time.</p><label className="field">First service date<input name="first" type="date" min={afterDays(businessDate,-31)} max={businessDate} defaultValue={businessDate} required disabled={request.busy}/></label><label className="field">Starting-date reason<textarea name="reason" required minLength={4} maxLength={500} disabled={request.busy}/></label><label className="pilot-check"><input type="checkbox" required disabled={request.busy}/>I reviewed the first service date and the absence of earlier history.</label><button className="primary" disabled={request.busy||request.blocked}>Start service ledger</button></form>:<p>An organization owner must choose the first service date.</p>}</>:<><div className="section-top"><div><h3>Next service day: {preview.next_service_date}</h3><p>Operational calendar date: {preview.civil_date} · {preview.time_zone}</p></div><span className={'pill '+(preview.can_close?'green':'amber')}>{preview.can_close?'Ready for review':preview.blockers.length+' items to resolve'}</span></div>{preview.blockers.length>0&&<div className="pilot-service-blockers"><h3>Before closing</h3><ul>{preview.blockers.map((b,i)=><li key={b.code+'/'+b.reservation_id+'/'+i}>{b.reservation_id&&<strong>{preview.rows.find(r=>r.reservation_id===b.reservation_id)?.guest_name??b.reservation_id}: </strong>}{blockerLabel(b.code)}{manager&&b.reservation_id&&b.code==='post_close_pricing_changed'&&<button className="text-button" disabled={request.busy} onClick={()=>setForward(b.reservation_id!)}>Review changed charges</button>}</li>)}</ul></div>}<ServiceInventoryReview inventory={preview.inventory_snapshot}/>{preview.totals&&<><p className="pilot-service-subtitle">{preview.can_close?'Reviewed allocation totals':'Totals below include only rows ready to close; blocked rows are excluded.'}</p><ServiceTotalsBreakdown ordinary={preview.ordinary_totals!} corrections={preview.correction_totals} total={preview.totals}/><PendingForwardList entries={preview.pending_adjustments}/></>}<div className="pilot-table-wrap"><table className="pilot-table"><caption className="sr-only">Service-day preview for {preview.next_service_date}</caption><thead><tr><th scope="col">Guest / reservation</th><th scope="col">Status</th><th scope="col">Service use</th><th scope="col">Allocation</th><th scope="col">Review</th></tr></thead><tbody>{preview.rows.map(row=><tr key={row.reservation_id}><td>{row.guest_name??'Guest'}<small>{row.reservation_id}</small></td><td>{row.status}</td><td>{serviceUsageLabel(row.occupied_night,row.allocation?.service_usage)}</td><td>{row.blocker?blockerLabel(row.blocker):usd(row.allocation?.total_minor)}{!row.blocker&&<small>{row.allocation_source==='quote'?'Accepted nightly quote':'Manager approved allocation'}</small>}</td><td>{manager&&<button className="text-button" disabled={request.busy} onClick={()=>setAllocation(row.reservation_id)}>Review allocation</button>}</td></tr>)}</tbody></table>{preview.rows.length===0&&<p className="pilot-empty">No candidate stays for this service day.</p>}</div>{manager&&<form className="pilot-service-confirm" key={preview.preview_hash+'/'+preview.corrections_hash} onSubmit={e=>{e.preventDefault();if(!preview.can_close||!preview.preview_hash||!preview.version||preview.api_version!==2||!preview.corrections_hash)return;void save({rpc:'close_service_day_v2',label:'Close service day '+preview.next_service_date,params:{p_request:crypto.randomUUID(),p_expected_version:preview.version,p_expected_preview_hash:preview.preview_hash,p_expected_corrections_hash:preview.corrections_hash}})}}><label className="pilot-check"><input type="checkbox" required disabled={request.busy||!preview.can_close||request.blocked}/>I reviewed the service-day allocations, inventory figures and signed corrections. The closed report will be preserved.</label><button className="primary" disabled={request.busy||!preview.can_close||request.blocked}>Close service day {preview.next_service_date}</button></form>}</>}</div></section><ClosedServiceReports key={actor+'/'+tenant+'/'+property+'/'+reportRevision} tenant={tenant} property={property} propertyName={propertyName} timeZone={timeZone} businessDate={businessDate} onReviewForward={manager?reservation=>setForward(reservation):undefined}/><Dialog open={!!forward} onOpenChange={open=>{if(!open&&!allocationBusy)setForward(null)}}><DialogContent className="reservation-dialog pilot-allocation-dialog"><DialogTitle>Review forward correction</DialogTitle><DialogDescription>Preserve original closed nights and review a separate dated correction.</DialogDescription>{forward&&<ServiceForwardPanel key={actor+'/'+tenant+'/'+property+'/'+forward} actor={actor} tenant={tenant} property={property} reservation={forward} onBusyChange={busy=>{setAllocationBusy(busy);onBusyChange(busy)}} onSaved={async()=>{await refresh();setReportRevision(v=>v+1)}}/>}</DialogContent></Dialog><Dialog open={!!allocation} onOpenChange={open=>{if(!open&&!allocationBusy)setAllocation(null)}}><DialogContent className="reservation-dialog pilot-allocation-dialog"><DialogTitle>Review nightly allocation</DialogTitle><DialogDescription>Reconcile the full stay charges before assigning them to service nights.</DialogDescription>{allocation&&<AllocationPanel key={actor+'/'+tenant+'/'+property+'/'+allocation} actor={actor} tenant={tenant} property={property} reservation={allocation} onBusyChange={busy=>{setAllocationBusy(busy);onBusyChange(busy)}} onSaved={async()=>{setAllocation(null);await refresh();setReportRevision(v=>v+1)}}/>}</DialogContent></Dialog></>;
}
function AllocationPanel({actor,tenant,property,reservation,onBusyChange,onSaved}:{actor:string;tenant:string;property:string;reservation:string;onBusyChange:(busy:boolean)=>void;onSaved:()=>Promise<void>}){
 const [data,setData]=useState<ServiceAllocation|null>(null),[readError,setReadError]=useState(''),[formError,setFormError]=useState('');const alive=useRef(true),sequence=useRef(0);
 const request=useServiceRequest('iratepilot-pms-pending-service-allocation:'+actor+':'+tenant+':'+property+':'+reservation,tenant,property,onBusyChange);
 async function refresh(){const seq=++sequence.current;setData(null);try{const result=await hotelRpc<ServiceAllocation>('service_allocation',{p_tenant:tenant,p_property:property,p_reservation:reservation});if(alive.current&&seq===sequence.current){setData(result);setReadError('')}}catch(e){if(alive.current&&seq===sequence.current)setReadError(e instanceof Error?e.message:'Unable to load allocation.')}}
 useEffect(()=>{alive.current=true;const seq=++sequence.current;hotelRpc<ServiceAllocation>('service_allocation',{p_tenant:tenant,p_property:property,p_reservation:reservation}).then(result=>{if(alive.current&&seq===sequence.current){setData(result);setReadError('')}}).catch(e=>{if(alive.current&&seq===sequence.current)setReadError(e instanceof Error?e.message:'Unable to load allocation.')});return()=>{alive.current=false}},[tenant,property,reservation]);
 const dates:string[]=[];if(data?.reservation.arrival&&data.reservation.departure)for(let date=data.reservation.arrival;date<data.reservation.departure&&dates.length<30;date=afterDays(date,1))dates.push(date);
 const save=(command:ServiceCommand)=>request.run(command,onSaved,()=>{void refresh()});
 return <>{(request.error||readError||formError)&&<div className="pilot-error" role="alert">{request.error||readError||formError}</div>}{request.pending?<PendingServiceRequest command={request.pending} busy={request.busy} onRetry={()=>void save(request.pending!)}/>:!data?<p>Loading current stay charges…</p>:<><p>{data.reservation.guest_name} · {data.reservation.arrival} to {data.reservation.departure}</p><p><b>Full amount to allocate: {data.total_minor==null?'Unknown — reconcile charges first':usd(data.total_minor)}</b> · Based on {data.financial_basis==='folio_charges'?'current folio charges':'booked charges'}.</p><div className="pilot-allocation-required"><h3>{data.component_totals_fixed?"Required full-stay component totals":"Classify the adjusted folio charges"}</h3>{data.component_totals_fixed?<dl>{serviceComponents.map(([key,label])=><div key={key}><dt>{label}</dt><dd>{usd(data.component_totals[key])}</dd></div>)}</dl>:<p>Generic folio adjustments need a manager to classify the full amount into accommodation, taxes, property fees, OTA fees, and other revenue. Document the basis in your reconciliation reason.</p>}</div><p>Enter the full stay allocation. Tax and property-fee values entered here are aggregate amounts; their City/State/Lodging and fee category split will remain unspecified. Previously closed amounts must stay unchanged.</p><form key={data.pricing_hash+'/'+data.reservation.source_version} onSubmit={e=>{e.preventDefault();setFormError('');const f=new FormData(e.currentTarget);try{const lines:AllocationInput[]=dates.map(date=>({date,...Object.fromEntries(serviceComponents.map(([key])=>[key,cents(f.get(date+'/'+key))]))} as AllocationInput));const sum=lines.reduce((total,line)=>total+serviceComponents.reduce((n,[key])=>n+line[key],0),0);if(data.component_totals_fixed)for(const [key,label] of serviceComponents){const entered=lines.reduce((sum,line)=>sum+line[key],0);if(entered!==data.component_totals[key])throw Error(label+' must total '+usd(data.component_totals[key])+'. Entered: '+usd(entered)+'.')}if(sum!==data.total_minor)throw Error('The nightly allocation total must equal '+usd(data.total_minor)+'. Entered: '+usd(sum)+'.');void save({rpc:'approve_service_allocation',label:'Approve nightly allocation for '+(data.reservation.guest_name??reservation),params:{p_request:crypto.randomUUID(),p_reservation:reservation,p_expected_source_version:data.reservation.source_version,p_expected_pricing_hash:data.pricing_hash,p_lines:lines,p_reason:formText(f,'reason').trim()}})}catch(error){setFormError(error instanceof Error?error.message:'Review allocation amounts.')}}}><div className="pilot-table-wrap"><table className="pilot-table pilot-allocation-table"><thead><tr><th scope="col">Night</th>{serviceComponents.map(([key,label])=><th scope="col" key={key}>{label} USD</th>)}</tr></thead><tbody>{dates.map(date=><tr key={date}><th scope="row">{date}</th>{serviceComponents.map(([key,label])=><td key={key}><label className="sr-only" htmlFor={date+'/'+key}>{label} {date}</label><input id={date+'/'+key} name={date+'/'+key} type="number" min="0" step="0.01" required disabled={request.busy||request.blocked} defaultValue={data.lines.find(line=>line.date===date)?(data.lines.find(line=>line.date===date)![key]/100).toFixed(2):'0.00'}/></td>)}</tr>)}</tbody></table></div><label className="field">Reconciliation reason<textarea name="reason" required minLength={4} maxLength={500} disabled={request.busy}/></label><label className="pilot-check"><input type="checkbox" required disabled={request.busy}/>I reviewed the service dates, occupancy and full charge allocation.</label><button className="primary" disabled={request.busy||request.blocked||data.total_minor==null||dates.length===0}>Approve nightly allocation</button></form></>}</>;
}

